import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DHmNT4rz.js";const m=JSON.parse('{"title":"Workflow","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/workflow.md","filePath":"develop/workflow.md","lastUpdated":null}'),i={name:"develop/workflow.md"};function n(d,e,s,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/workflow.md" target="_blank" rel="noreferrer"><code>.agents/workflow.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h1><h2 id="essential-commands" tabindex="-1">Essential Commands <a class="header-anchor" href="#essential-commands" aria-label="Permalink to &quot;Essential Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>vp run dev</code></td><td>Start all dev servers</td></tr><tr><td><code>vp check</code></td><td>Run package-local format, lint, and typecheck for the current package</td></tr><tr><td><code>vp check --fix</code></td><td>Run package-local format, lint fixes, and typecheck</td></tr><tr><td><code>vp run -w fix</code></td><td>Format + lint + typecheck after substantial code/config work</td></tr><tr><td><code>vp run build</code></td><td>Build all packages</td></tr></tbody></table><h2 id="validation-timing" tabindex="-1">Validation Timing <a class="header-anchor" href="#validation-timing" aria-label="Permalink to &quot;Validation Timing&quot;">​</a></h2><p>Default to running fixes after making code or configuration changes. Run the narrowest fix command that covers the touched surface before handing work back to the user.</p><ul><li>For scoped app or package changes, run package-local <code>vp check --fix</code> from the changed app or package.</li><li>For cross-package, root config, generated artifact, or workspace-wide changes, run <code>vp run -w fix</code>.</li><li>For larger planned work, such as implementing a <code>plan.md</code>, run fixes often enough to catch drift: after substantial milestones/phases and once more before final handoff. Do not run a broad workspace fix after every tiny intermediate edit when a focused package fix or milestone fix covers the work.</li><li>If a fix command fails, inspect the output, fix what is in scope, and rerun the same command until it passes or a real blocker remains.</li><li>Do not reach for root filtered check commands when a package-local <code>vp check --fix</code> covers the changed surface.</li></ul><p><code>vp check --fix</code> and <code>vp run -w fix</code> format (Oxfmt), lint (Oxlint), and type-check in one pass. Treat fix commands as the normal cleanup and validation path after edits.</p><p>For markdown-only edits, small documentation tweaks, or other changes that cannot affect formatting, linting, typechecking, build output, or runtime behavior, run an available narrow formatter/fix only when it applies cleanly to the touched surface. Otherwise, state that no code/config fix command was applicable. Staged files may be auto-checked on <code>git commit</code> via Vite Plus hooks; do not rely on those hooks as the first fix pass when edits have already been made.</p><h2 id="completion-claims" tabindex="-1">Completion Claims <a class="header-anchor" href="#completion-claims" aria-label="Permalink to &quot;Completion Claims&quot;">​</a></h2><ul><li>Do not report implementation, migration, validation, or cleanup work as complete until the relevant edits or commands have run and you have checked the resulting files or command output.</li><li>If a workflow depends on generated artifacts or CLI state, verify that state directly instead of inferring completion from intent alone.</li></ul><h2 id="auxiliary-static-analysis" tabindex="-1">Auxiliary Static Analysis <a class="header-anchor" href="#auxiliary-static-analysis" aria-label="Permalink to &quot;Auxiliary Static Analysis&quot;">​</a></h2><p>Fallow is an auxiliary cleanup signal, not part of the default validation path.</p><ul><li>Use <code>vp run fallow</code> only when the user explicitly asks for auxiliary cleanup signals after big features or broad refactors have landed.</li><li>Do not add Fallow to commit hooks, <code>fix</code>, or normal handoff validation unless the user explicitly asks.</li><li>Treat Fallow findings as review prompts. Verify framework entry points, dynamic usage, generated files, and package boundaries before deleting or suppressing code.</li></ul><h2 id="feature-workflows" tabindex="-1">Feature Workflows <a class="header-anchor" href="#feature-workflows" aria-label="Permalink to &quot;Feature Workflows&quot;">​</a></h2><p>For end-to-end feature implementation order across <code>packages/db</code>, <code>packages/core</code>, <code>packages/app</code>, <code>packages/jobs</code>, <code>packages/api</code>, and <code>apps/web</code>, use <a href="/SaaSWeave/develop/end-to-end-features">End-to-end feature workflow</a>. Keep this file focused on validation timing, commands, and migration safety.</p><h2 id="database-schema-changes" tabindex="-1">Database Schema Changes <a class="header-anchor" href="#database-schema-changes" aria-label="Permalink to &quot;Database Schema Changes&quot;">​</a></h2><ol><li>Edit schemas in <code>packages/db/src/schema/</code></li><li>Run <code>vp run db:generate</code> to create migration files</li><li><strong>Check <code>DATABASE_URL</code></strong> — must point to localhost/127.0.0.1. If it looks like a production URL, <strong>stop and warn the user</strong>.</li><li>Run <code>vp run db:migrate</code> to apply. Features will silently fail without applied migrations.</li></ol><h2 id="other-commands" tabindex="-1">Other Commands <a class="header-anchor" href="#other-commands" aria-label="Permalink to &quot;Other Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>vp run db:dev:start</code></td><td>Start local PostgreSQL (Docker)</td></tr><tr><td><code>vp run db:dev:stop</code></td><td>Stop local PostgreSQL</td></tr><tr><td><code>vp run db:generate</code></td><td>Generate migration files</td></tr><tr><td><code>vp run db:migrate</code></td><td>Apply migrations</td></tr><tr><td><code>vp run db:studio</code></td><td>Open Drizzle Studio</td></tr></tbody></table><h2 id="ui-components-and-shadcn" tabindex="-1">UI Components And shadcn <a class="header-anchor" href="#ui-components-and-shadcn" aria-label="Permalink to &quot;UI Components And shadcn&quot;">​</a></h2><p>For UI component selection, shadcn install decisions, and visual coherence rules, use <a href="/SaaSWeave/develop/ui">UI guidelines</a>. Keep the detailed UI policy there rather than duplicating it in workflow docs.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Follow <a href="/SaaSWeave/develop/testing">Testing policy</a>. Run the narrowest relevant tests when code changes affect behavior, contracts, bug fixes, or surfaces with nearby test coverage. Use e2e tests for browser workflows and integration paths that unit tests cannot cover.</p><h2 id="commits" tabindex="-1">Commits <a class="header-anchor" href="#commits" aria-label="Permalink to &quot;Commits&quot;">​</a></h2><p>Use Conventional Commit format. Run the appropriate fix command before staging or committing code/config edits; do not rely on staging hooks as the first cleanup pass.</p>',26)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
